  const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',mood:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM8 14s1 3 4 3 4-3 4-3M8 9h.01M16 9h.01',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',health:'M3 12h4l3-8 4 16 3-8h4',location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',wheel:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 3v18M3 12h18M6 6l12 12M18 6 6 18',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 0 1-1-4 9 9 0 0 1 18-1ZM7 10h10M7 14h7',pets:'M9 13c-1 1-5 3-5 6 0 4 5 0 8 0s8 4 8 0c0-3-4-5-5-6-2-2-4-2-6 0ZM8 7a2 3 0 1 1-4 0 2 3 0 0 1 4 0ZM20 7a2 3 0 1 1-4 0 2 3 0 0 1 4 0ZM14 5a2 3 0 1 1-4 0 2 3 0 0 1 4 0Z',games:'M7 8h10c3 0 6 11 3 12-2 1-4-4-5-4H9c-1 0-3 5-5 4C1 19 4 8 7 8ZM8 10v5M5.5 12.5h5M16 11h.01M18 14h.01',calendar:'M4 5h16v16H4ZM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 18h2',memories:'M3 4h18v16H3ZM3 16l6-6 6 6 3-3 3 3M16 8h.01',vault:'M3 7h18v14H3ZM3 7l4-4h10l4 4M9 11h6M12 11v5',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3',stats:'M4 21V11h4v10ZM10 21V4h4v17ZM16 21V8h4v13'};
  const svgIcon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.heart}"/></svg>`;
  const nav=[['NHÀ CỦA CHÚNG MÌNH',[['home','Tổng quan'],['mood','Tâm trạng hôm nay'],['health','Trung tâm sức khỏe'],['location','Vị trí của nhau']]],['THÊM MỘT CHÚT VUI',[['wheel','Vòng quay may mắn'],['chat','Góc chuyện trò'],['pets','Thú cưng chung'],['games','Chơi cùng nhau']]],['GIỮ LẠI YÊU THƯƠNG',[['calendar','Lịch & kỷ niệm'],['memories','Khoảnh khắc'],['vault','Kho báu của mình'],['stats','Hành trình yêu'],['profile','Hồ sơ & ghép đôi']]]];
  const labels=Object.fromEntries(nav.flatMap(x=>x[1])); labels.pair='Ghép đôi';
  let experience=null;
  const extraPages={};
  let S=null, sock=null, page='home', authMode='login', toastTimer, refreshTimer, month=new Date(new Date().getFullYear(),new Date().getMonth(),1), selectedDate=today(), selectedWheel=null, selectedPet=null, selectedGame=null, vaultKind='journal', mediaFilter='all', memorySearch='', spinning=false, wheelRotation=0, pendingAttachment=null, messageCache=[], online=false, watchId=null, locationSendAt=0, soundEnabled=localStorage.getItem('love-sound')==='on', audioContext=null;
  let cameraStream=null, recorder=null, recordStream=null, recordingChunks=[], callStream=null, peer=null, incoming=null, callActive=false, callVideo=true, iceQueue=[], ringTimer=null;
