  function editProfile(){const p=S.me;editorPhoto=null;modal('Một chút về bạn',`<form id="profileForm" class="form-grid"><div class="full">${field('name','Tên hiển thị','text',p.name,'required maxlength="70"')}</div>${field('birthday','Ngày tháng năm sinh','date',p.birthday,`max="${today()}"`)}${select('gender','Giới tính',[['other','Khác / chưa chọn'],['female','Nữ'],['male','Nam']],p.gender)}${select('interestedIn','Bạn quan tâm đến',[['all','Mọi giới'],['female','Nữ'],['male','Nam'],['other','Khác']],p.interestedIn)}${select('status','Trạng thái nhanh',[['Đang ở đây','☀ Đang ở đây'],['💼 Đang đi làm','💼 Đang đi làm'],['📚 Đang đi học','📚 Đang đi học'],['😴 Đang ngủ','😴 Đang ngủ'],['🍜 Đang ăn','🍜 Đang ăn'],['🚻 Đang đi vệ sinh','🚻 Đang đi vệ sinh'],['🌿 Đang đi chơi','🌿 Đang đi chơi'],['🤗 Cần một cái ôm','🤗 Cần một cái ôm']],p.status)}${area('bio','Đôi dòng về bạn',p.bio)}${fileField(p.avatar?{url:p.avatar,mime:'image/jpeg'}:null)}${area('healthStatus','Tình trạng sức khỏe / cách bạn muốn được chăm',p.healthStatus)}${check('shareHealth','Cho người thương thấy tình trạng sức khỏe trên hồ sơ',p.shareHealth)}${footer('Lưu hồ sơ ♡')}</form>`);$('#editorFile').accept='image/*';bindFilePreview();bindForm('#profileForm',async(b,form)=>{let avatarUrl=p.avatar;if($('#editorFile').files[0])avatarUrl=(await uploadFile($('#editorFile').files[0])).url;await api('/profile','PUT',{...p,...b,avatar:avatarUrl,shareHealth:form.elements.shareHealth.checked});$('#editor').close();await refresh();toast('Hồ sơ đã được cập nhật.');});}
  function adoptPet(preset='cat'){modal('Đón một người bạn nhỏ',`<form id="adoptForm"><div class="pet-gallery">${Object.entries(species).map(([k,v])=>`<button type="button" class="species-button ${k===preset?'selected':''}" data-species="${k}">${petSvg(k)}${v}</button>`).join('')}</div><input name="species" type="hidden" value="${preset}"><div style="margin-top:22px">${field('name','Đặt một cái tên thật dễ thương','text','','required maxlength="50" placeholder="Mochi, Bông, Đậu, Mây…"')}</div><p class="form-note" style="margin-top:13px">Bé sẽ sống chung trong nhà của hai bạn. Cho ăn, tắm, ngủ, đi dạo và chơi để lên cấp.</p>${footer('Chào mừng về nhà ♡')}</form>`);$$('[data-species]',$('#editor')).forEach(b=>b.onclick=()=>{$$('[data-species]',$('#editor')).forEach(x=>x.classList.toggle('selected',x===b));$('[name=species]',$('#adoptForm')).value=b.dataset.species;});bindForm('#adoptForm',async b=>{const p=await api('/pets','POST',b);selectedPet=p.id;$('#editor').close();await refresh();toast(`Chào ${p.name}, từ nay có hai mình chăm bé ♡`);playPetSound(p.species);});}
