  async function loadMessages(){if(page!=='chat')return;const items=await api('/messages');messageCache=items;const list=$('#messages');if(!list)return;const atBottom=list.scrollHeight-list.scrollTop-list.clientHeight<90,oldIds=list.dataset.ids;const ids=items.map(x=>x.id).join(',');if(oldIds===ids)return;list.dataset.ids=ids;list.innerHTML=items.length?items.map(m=>{const mine=m.owner===S.me.id&&!m.legacy,p=person(m.owner);return `<article class="message ${mine?'mine':''}">${avatar(p,'small',!mine)}<div class="bubble"><b>${esc(m.legacy?m.sender:personName(m.owner))}</b>${m.attachment?recordMedia(m.attachment,'',''):''}<p>${esc(m.body)}</p><time>${time(m.createdAt)} · ${fmt(m.createdAt.slice(0,10)).slice(0,5)}</time></div></article>`;}).join(''):'<div style="margin:auto;text-align:center;color:var(--muted)"><span style="font-size:40px">♡</span><p style="font-size:11px;margin-top:12px">Một câu chào cũng là bắt đầu của một điều đẹp.</p></div>';if(atBottom||!oldIds){list.scrollTop=list.scrollHeight;$$('img,video',list).forEach(el=>el.addEventListener('load',()=>list.scrollTop=list.scrollHeight,{once:true}));}}
