  async function sendMessage(body){body=String(body||'').trim();if(!body&&!pendingAttachment)return;const attachment=pendingAttachment;await api('/messages','POST',{body,attachment});pendingAttachment=null;if($('#messageInput'))$('#messageInput').value='';showAttachment();await loadMessages();const list=$('#messages');if(list)list.scrollTop=list.scrollHeight;}
  async function enableLocation(){if(!navigator.geolocation)throw new Error('Trình duyệt chưa hỗ trợ định vị.');await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(async pos=>{try{await publishPosition(pos);startLocationWatch();await refresh();toast('Đã bật chia sẻ vị trí khi trang đang mở.');resolve();}catch(e){reject(e);}},()=>reject(new Error('Chưa lấy được vị trí. Hãy cấp quyền định vị cho localhost hoặc HTTPS.')),{enableHighAccuracy:true,timeout:20000,maximumAge:0}));}
