  function startLocationWatch(){if(watchId!==null||!navigator.geolocation)return;watchId=navigator.geolocation.watchPosition(async pos=>{if(!S?.locations.enabled||Date.now()-locationSendAt<10000)return;try{await publishPosition(pos);await refresh(page==='location');}catch(e){toast(e.message,true);}},e=>{if(e.code===1)disableLocation().catch(()=>{});},{enableHighAccuracy:true,maximumAge:10000,timeout:25000});}
