  function tone(frequency,duration=.18,delay=0,type='sine',volume=.08){if(!soundEnabled)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime+delay;o.type=type;o.frequency.setValueAtTime(frequency,t);o.frequency.exponentialRampToValueAtTime(frequency*.65,t+duration);gain.gain.setValueAtTime(.001,t);gain.gain.exponentialRampToValueAtTime(volume,t+.02);gain.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(gain);gain.connect(audioContext.destination);o.start(t);o.stop(t+duration+.01);}catch{}}
  function playPetSound(kind){
    if(!soundEnabled)return;
    // Original synthesized animal voices; generated locally without external files.
    try{
      audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();
      const voices={cat:{f:[480,820,550,260],length:.8,type:'triangle',filter:1350},dog:{f:[190,120,75],length:.22,type:'sawtooth',filter:850,repeat:2},bunny:{f:[1100,1500,1200],length:.18,type:'sine',filter:2300,repeat:3},fox:{f:[720,1300,450],length:.3,type:'triangle',filter:1900,repeat:2},panda:{f:[140,190,95],length:.6,type:'triangle',filter:600},dragon:{f:[85,140,55],length:1,type:'sawtooth',filter:400},penguin:{f:[550,850,480],length:.4,type:'sawtooth',filter:1100,repeat:2},bear:{f:[90,120,65],length:.7,type:'triangle',filter:500}};
      const v=voices[kind]||voices.cat;
      for(let j=0;j<(v.repeat||1);j++){
        const start=audioContext.currentTime+j*(v.length+.1),o=audioContext.createOscillator(),g=audioContext.createGain(),filter=audioContext.createBiquadFilter();
        o.type=v.type;v.f.forEach((f,i)=>{if(i===0)o.frequency.setValueAtTime(f,start);else o.frequency.exponentialRampToValueAtTime(f,start+i*v.length/(v.f.length-1));});
        filter.type='lowpass';filter.frequency.setValueAtTime(v.filter,start);filter.frequency.exponentialRampToValueAtTime(v.filter*.5,start+v.length);filter.Q.value=2;
        g.gain.setValueAtTime(.001,start);g.gain.exponentialRampToValueAtTime(.15,start+.025);g.gain.exponentialRampToValueAtTime(.001,start+v.length);
        o.connect(filter);filter.connect(g);g.connect(audioContext.destination);o.start(start);o.stop(start+v.length+.01);
      }
    }catch{}
  }
  let recordingTimeout=null;
  async function voiceRecord(){if(recorder?.state==='recording'){stopRecording(false);return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Trình duyệt này chưa hỗ trợ ghi âm. Bạn vẫn có thể gửi tệp âm thanh.');recordStream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm','audio/ogg','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});recordingChunks=[];recorder.ondataavailable=e=>{if(e.data.size)recordingChunks.push(e.data);};recorder.onstop=async()=>{if(recorder?.discard){recordingChunks=[];return;}try{const mime=(recorder.mimeType||'audio/webm').split(';')[0],blob=new Blob(recordingChunks,{type:mime});if(blob.size){pendingAttachment=await uploadFile(new File([blob],`loi-nhan-${today()}.${mime==='audio/mp4'?'m4a':mime==='audio/ogg'?'ogg':'webm'}`,{type:mime}));showAttachment();toast('Đã thu âm. Bấm gửi để chia sẻ với người thương.');}}catch(e){toast(e.message,true);}finally{recordingChunks=[];}};recorder.start();$('#voiceRecord').textContent='◼';$('#voiceRecord').style.color='#b34e5b';toast('Đang ghi âm… bấm nút lần nữa để dừng (tối đa 2 phút).');recordingTimeout=setTimeout(()=>stopRecording(false),120000);}
  function stopRecording(discard=false){clearTimeout(recordingTimeout);if(recorder?.state==='recording'){recorder.discard=discard;recorder.stop();}recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if($('#voiceRecord')){$('#voiceRecord').textContent='♩';$('#voiceRecord').style.color='';}}
  async function spinWheel(){if(spinning)return;const w=data('wheel').find(x=>x.id===selectedWheel);if(!w)return;spinning=true;const button=$('[data-action=spin]');button.disabled=true;try{const result=await api(`/wheels/${w.id}/spin`,'POST',{}),disc=$('#wheelDisc'),target=(360-((result.index+.5)*360/result.count))%360,delta=(target-(wheelRotation%360)+360)%360;wheelRotation+=360*6+delta;disc.style.transform=`rotate(${wheelRotation}deg)`;$('#wheelResult').innerHTML='<p>MỘT CHÚT MAY MẮN ĐANG XOAY</p><strong>Đợi một chút nhé…</strong>';for(let i=0;i<12;i++)tone(700-i*22,.04,i*.14,'sine',.025);await new Promise(r=>setTimeout(r,5100));if(page==='wheel')$('#wheelResult').innerHTML=`<p>VŨ TRỤ CHỌN ĐIỀU NÀY CHO HAI MÌNH</p><strong>${esc(result.result)}</strong>`;tone(660,.25);tone(880,.3,.17);toast('Kết quả: '+result.result+' ♡');await refresh(false);if(page==='wheel'){const log=$('#spinHistory');if(log)log.innerHTML=data('spin').filter(x=>x.wheelId===w.id).slice(0,8).map(x=>`<div class="spin-log"><div><b>${esc(x.result)}</b><small>${esc(personName(x.owner))}</small></div><small>${time(x.createdAt)}</small></div>`).join('');}}catch(e){toast(e.message,true);}finally{spinning=false;if(button?.isConnected)button.disabled=false;}}
  async function starterWheels(){for(const [title,options]of [['Hôm nay ăn gì?',['Bún bò','Cơm nhà','Pizza','Mì cay','Phở','Sushi']],['Hẹn hò ở đâu?',['Đi dạo công viên','Cà phê yên tĩnh','Xem phim','Nấu ăn cùng nhau','Đi nhà sách','Ngắm hoàng hôn']],['Một chút yêu thương',['Ôm nhau 20 giây','Nói 3 điều biết ơn','Gửi một tấm selfie','Kể một kỷ niệm vui','Hát một câu cho nhau','Lên lịch hẹn cuối tuần']]] )await api('/items/wheel','POST',{title,options,shared:true});await refresh();toast('Đã thêm 3 vòng quay để bắt đầu ♡');}
  async function reloadPair(){endCall(false);sock?.disconnect();await refresh(false);connectSocket();render();}
  async function setupPeer(video){if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)throw new Error('Gọi điện cần trình duyệt hỗ trợ và localhost hoặc HTTPS.');callStream=await navigator.mediaDevices.getUserMedia({audio:true,video:video?{facingMode:'user',width:{ideal:1280},height:{ideal:720}}:false});const config=await api('/rtc-config');peer=new RTCPeerConnection(config);iceQueue=[];callStream.getTracks().forEach(track=>peer.addTrack(track,callStream));$('#localVideo').srcObject=callStream;$('#localVideo').hidden=!video;$('#cameraCall').hidden=!video;$('#muteCall').textContent='Tắt mic';$('#cameraCall').textContent='Tắt camera';$('#remoteVideo').srcObject=null;$('#callPlaceholder').hidden=false;peer.onicecandidate=e=>{if(e.candidate)sock?.emit('call:signal',{candidate:e.candidate.toJSON()});};peer.ontrack=e=>{$('#remoteVideo').srcObject=e.streams[0]||new MediaStream([e.track]);$('#remoteVideo').play().catch(()=>{});$('#callPlaceholder').hidden=true;};peer.onconnectionstatechange=()=>{if(!peer)return;const status=peer.connectionState;if(status==='connected'){$('#callStatus').textContent='Đã kết nối · đang ở cạnh nhau ♡';clearTimeout(ringTimer);}if(status==='failed'){$('#callStatus').textContent='Chưa kết nối được. Mạng hiện tại có thể cần máy chủ TURN.';toast('Kết nối gọi chưa thành công. Có thể cần cấu hình STUN/TURN cho mạng này.',true);}if(status==='disconnected')$('#callStatus').textContent='Kết nối đang gián đoạn…';};}
  async function startCall(video){if(!S.partner)throw new Error('Ghép đôi để gọi người thương nhé.');if(!sock?.connected)throw new Error('Máy chủ trò chuyện đang mất kết nối.');if(callActive||incoming)throw new Error('Bạn đang có một cuộc gọi.');callVideo=video;try{await setupPeer(video);callActive=true;$('#callStatus').textContent='Đang gọi '+S.partner.name+'…';$('#callDialog').showModal();sock.emit('call:invite',{video});ringTimer=setTimeout(()=>{if(callActive&&peer?.connectionState!=='connected'){toast('Người thương chưa nghe máy.');endCall();}},45000);}catch(e){endCall(false);throw new Error('Chưa mở được cuộc gọi: '+e.message);}}
  async function acceptCall(){if(!incoming)return;callVideo=incoming.video;try{await setupPeer(callVideo);callActive=true;$('#incomingCall').hidden=true;$('#callStatus').textContent='Đang kết nối với '+incoming.name+'…';$('#callDialog').showModal();sock.emit('call:accept');incoming=null;}catch(e){endCall();throw new Error('Hãy cấp quyền mic/camera rồi gọi lại. '+e.message);}}
  async function handleSignal(payload){if(!peer||!callActive)return;try{if(payload.description){await peer.setRemoteDescription(payload.description);for(const c of iceQueue)await peer.addIceCandidate(c);iceQueue=[];if(payload.description.type==='offer'){const answer=await peer.createAnswer();await peer.setLocalDescription(answer);sock.emit('call:signal',{description:peer.localDescription.toJSON()});}}if(payload.candidate){if(peer.remoteDescription)await peer.addIceCandidate(payload.candidate);else iceQueue.push(payload.candidate);}}catch(e){toast('Có gián đoạn khi thiết lập cuộc gọi. Hãy thử gọi lại.',true);}}
  function endCall(send=true){clearTimeout(ringTimer);if(send&&(callActive||incoming))sock?.emit('call:end');callActive=false;incoming=null;$('#incomingCall').hidden=true;if(peer){peer.onconnectionstatechange=null;peer.close();peer=null;}callStream?.getTracks().forEach(t=>t.stop());callStream=null;$('#localVideo').srcObject=null;$('#remoteVideo').srcObject=null;if($('#callDialog').open)$('#callDialog').close();iceQueue=[];}
  let typingTimer=null;
  function connectSocket(){sock?.disconnect();if(!window.io){toast('Chưa tải được kết nối thời gian thực. Thử tải lại trang.',true);return;}sock=io({autoConnect:true});sock.on('connect',()=>{$('#connectionStatus').textContent=S?.partner?'Hai người, một thế giới':'Ngôi nhà đang trực tuyến';online=true;refresh().catch(()=>{});});sock.on('disconnect',()=>{$('#connectionStatus').textContent='Đang kết nối lại…';online=false;if(callActive)endCall(false);});sock.on('connect_error',()=>{$('#connectionStatus').textContent='Chưa kết nối được';});sock.on('sync',({kind})=>{if(!S)return;if(kind==='message'){if(page==='chat')loadMessages().catch(()=>{});else{toast('Có lời nhắn mới từ không gian chung ♡');tone(880,.1);}return;}clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(e=>toast(e.message,true)),220);});sock.on('pair:changed',async()=>{try{await reloadPair();}catch(e){toast(e.message,true);}});sock.on('typing',({id})=>{if(id===S?.me.id||!$('#typingLine'))return;$('#typingLine').textContent=personName(id)+' đang viết…';clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if($('#typingLine'))$('#typingLine').textContent='';},2200);});sock.on('presence',({id,online:isOnline})=>{if($('#chatPresence')&&id===S?.partner?.id)$('#chatPresence').textContent=isOnline?'Người thương đang ở đây ♡':'Người thương vừa rời phòng';});sock.on('call:incoming',data=>{if(callActive||incoming)return;incoming=data;$('#incomingName').textContent=data.name;$('#incomingCall').hidden=false;tone(660,.25);tone(880,.3,.35);});sock.on('call:accepted',async()=>{if(!peer||!callActive)return;try{$('#callStatus').textContent='Người thương đã nghe máy · đang kết nối…';const offer=await peer.createOffer();await peer.setLocalDescription(offer);sock.emit('call:signal',{description:peer.localDescription.toJSON()});}catch{toast('Không thiết lập được cuộc gọi.',true);endCall();}});sock.on('call:signal',handleSignal);sock.on('call:ended',()=>endCall(false));sock.on('call:dismiss',()=>{incoming=null;$('#incomingCall').hidden=true;});sock.on('call:unavailable',message=>{toast(message,true);endCall(false);});}
  function showAuth(){experience?.beforeRender();S=null;endCall(false);sock?.disconnect();sock=null;stopRecording(true);stopCamera();pendingAttachment=null;messageCache=[];if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;$$('dialog[open]').forEach(x=>x.close());$('#app').hidden=true;$('#auth').hidden=false;$('#authError').textContent='';}
  function enterApp(state){S=state;$('#auth').hidden=true;$('#app').hidden=false;$('#authForm').reset();page=labels[location.hash.slice(1)]?location.hash.slice(1):'home';render();connectSocket();if(S.locations.enabled)startLocationWatch();}
  function changeAuth(mode){authMode=mode;$$('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b.dataset.authMode===mode));$('#registerName').hidden=mode!=='register';$('[name=name]',$('#authForm')).required=mode==='register';$('#authTitle').textContent=mode==='register'?'Bắt đầu chuyện của mình.':'Thật vui vì bạn ở đây.';$('#authSubtitle').textContent=mode==='register'?'Một tài khoản cho bạn, một lời mời cho người thương.':'Đăng nhập để về với không gian của hai mình.';$('#authSubmit').innerHTML=mode==='register'?'Tạo ngôi nhà của bạn <span>→</span>':'Về nhà thôi <span>→</span>';$('#authPassword').autocomplete=mode==='register'?'new-password':'current-password';$('#authError').textContent='';}
  async function action(name,button){
    if(name==='edit-profile')return editProfile();
    if(name==='prompt'){promptIndex=(promptIndex+1)%prompts.length;return render();}
    if(name==='adopt')return adoptPet();
    if(name==='pet-sound'){if(!soundEnabled){soundEnabled=true;localStorage.setItem('love-sound','on');$('#soundButton').textContent='♫';}return playPetSound(data('pet').find(p=>p.id===selectedPet)?.species);}
    if(name==='spin')return spinWheel();
    if(name==='starter-wheels')return starterWheels();
    if(name==='leave-game'){selectedGame=null;return render();}
    if(name==='update-location')return enableLocation();
    if(name==='random-memory'){const m=data('memory');if(!m.length){toast('Lưu khoảnh khắc đầu tiên rồi quay lại đây nhé ♡');return editItem('memory');}return viewItem(m[Math.floor(Math.random()*m.length)].id);}
    if(name==='remove-attachment'){pendingAttachment=null;return showAttachment();}
    if(name==='voice')return voiceRecord();
    if(name==='logout'){await api('/auth/logout','POST',{});showAuth();return;}
    if(name==='invite'){const {code,expires}=await api('/pair/invite','POST',{});$('#inviteResult').innerHTML=`<div class="invite-code">${esc(code)}</div><p class="form-note">Dùng trước ${new Date(expires).toLocaleString('vi-VN')}</p><button class="text-button" data-copy="${code}">Sao chép mã mời ⧉</button>`;return;}
    if(name==='unlink')return confirmDialog('Tách không gian của hai người','Mỗi người giữ các bản ghi và tệp do mình tạo. Các tham chiếu tệp của người kia sẽ được gỡ. Chat, game và thú cưng do ai tạo sẽ chuyển về không gian người đó. Chia sẻ vị trí được tắt cho cả hai.',async b=>{await api('/pair/unlink','POST',b);selectedGame=null;selectedPet=null;selectedWheel=null;await reloadPair();toast('Đã tách không gian.');},'TÁCH ĐÔI');
    if(name==='export'){const result=await api('/export'),blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`chuyen-hai-minh-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Đã tải bản sao dữ liệu.');}
    if(name==='import-legacy')return confirmDialog('Giữ lại kỷ niệm trước đây','Nhập ảnh/video, sự kiện, điều ước, nhật ký và lời nhắn của phiên bản trước vào không gian hiện tại. Chỉ thực hiện một lần; tệp gốc vẫn được giữ.',async()=>{const r=await api('/legacy/import','POST',{});await refresh();toast(`Đã giữ lại ${r.count} nội dung cũ ♡`);});
    if(name==='password'){modal('Đổi mật khẩu',`<form id="passwordForm" class="form-grid"><div class="full">${field('current','Mật khẩu hiện tại','password','','required maxlength="128" autocomplete="current-password"')}</div><div class="full">${field('password','Mật khẩu mới','password','','required minlength="8" maxlength="128" autocomplete="new-password"')}</div>${footer('Đổi mật khẩu')}</form>`);bindForm('#passwordForm',async b=>{await api('/auth/password','POST',b);$('#editor').close();connectSocket();toast('Đã đổi mật khẩu và đăng xuất các phiên cũ.');});return;}
  }
  document.addEventListener('click',async e=>{
    const b=e.target.closest('button,a,[data-view],[data-day]');if(!b)return;const d=b.dataset;
    try{
      if(d.close){e.preventDefault();$('#'+d.close).close();return;}
      if(d.nav){e.preventDefault();return navigate(d.nav);}
      if(d.authMode)return changeAuth(d.authMode);
      if(!S)return;
      if(d.add)return editItem(d.add);
      if(d.edit)return editItem(d.edit,d.id);
      if(d.delete)return confirmDialog('Xóa nội dung này?', 'Nội dung sẽ được gỡ khỏi không gian của hai bạn. Tệp gốc vẫn được giữ trong kho máy chủ.',async()=>{await api(`/items/${d.delete}/${d.id}`,'DELETE');await refresh();toast('Đã xóa nội dung.');});
      if(d.complete){const item=data(d.complete).find(x=>x.id===d.id);await api(`/items/${d.complete}/${d.id}/complete`,'PATCH',{completed:!item.completed});await refresh();return;}
      if(d.month){if(d.month==='today'){month=new Date(new Date().getFullYear(),new Date().getMonth(),1);selectedDate=today();}else month=new Date(month.getFullYear(),month.getMonth()+Number(d.month),1);return render();}
      if(d.day){selectedDate=d.day;return render();}
      if(d.wheel){if(spinning)return toast('Chờ vòng quay dừng trước nhé.');selectedWheel=d.wheel;wheelRotation=0;return render();}
      if(d.pet){selectedPet=d.pet;return render();}
      if(d.adopt)return adoptPet(d.adopt);
      if(d.petAction){b.disabled=true;const p=await api(`/pets/${d.id}/action`,'POST',{action:d.petAction});await refresh();playPetSound(p.species);return toast(`${petActions[d.petAction][2]} · +${d.petAction==='play'?15:d.petAction==='walk'?12:d.petAction==='bath'?10:d.petAction==='cuddle'?5:8} XP, +3 xu ♡`);}
      if(d.accessory){await api(`/pets/${d.id}/action`,'POST',{action:'accessory',accessory:d.accessory});await refresh();return toast('Bé có diện mạo mới rồi ♡');}
      if(d.newGame){const g=await api('/games','POST',{kind:d.newGame});selectedGame=g.id;await refresh();return;}
      if(d.openGame){selectedGame=d.openGame;return render();}
      if(d.joinGame){await api(`/games/${d.joinGame}/join`,'POST',{});await refresh();return;}
      if(d.move!==undefined||d.choice){const g=data('game').find(x=>x.id===selectedGame);if(!g)return;await api(`/games/${g.id}/move`,'POST',d.choice?{choice:d.choice}:{index:Number(d.move)});await refresh();return;}
      if(d.vault){vaultKind=d.vault;return render();}
      if(d.cycleOwner){cycleOwner=d.cycleOwner;return render();}
      if(d.mediaFilter){mediaFilter=d.mediaFilter;return render();}
      if(d.view)return viewItem(d.view);
      if(d.sticker)return sendMessage(d.sticker);
      if(d.call)return startCall(d.call==='video').catch(err=>toast(err.message,true));
      if(d.copy){try{await navigator.clipboard.writeText(d.copy);toast('Đã sao chép mã mời.');}catch{toast('Chạm giữ mã phía trên để sao chép nhé.');}return;}
      if(d.action){b.disabled=true;try{await action(d.action,b);}finally{if(b.isConnected)b.disabled=false;}}
    }catch(err){if(b.isConnected)b.disabled=false;toast(err.message,true);}
  });
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-day]')){e.preventDefault();e.target.click();}});
  let tiltedCard=null,tiltFrame=0;
  document.addEventListener('pointermove',e=>{
    if(e.pointerType!=='mouse'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    const card=e.target.closest('.record-card,.game-tile');
    if(tiltedCard&&tiltedCard!==card)tiltedCard.style.transform='';tiltedCard=card;
    cancelAnimationFrame(tiltFrame);if(!card)return;
    const x=e.clientX,y=e.clientY;tiltFrame=requestAnimationFrame(()=>{const r=card.getBoundingClientRect();card.style.transform=`perspective(1000px) rotateX(${(-(y-r.top-r.height/2)/r.height*5).toFixed(2)}deg) rotateY(${((x-r.left-r.width/2)/r.width*6).toFixed(2)}deg) translateY(-3px)`;});
  });
  document.addEventListener('pointerout',e=>{if(tiltedCard&&!tiltedCard.contains(e.relatedTarget)){cancelAnimationFrame(tiltFrame);tiltedCard.style.transform='';tiltedCard=null;}});
