  $('#navigation').innerHTML=nav.map(([title,items])=>`<p class="nav-label">${title}</p>${items.map(([k,t])=>`<a href="#${k}" class="nav-link" data-nav="${k}">${svgIcon(k)}<span>${t}</span>${k==='home'?'<span class="nav-dot"></span>':''}</a>`).join('')}`).join('');
  $('#authForm').onsubmit=async e=>{e.preventDefault();const button=$('#authSubmit');button.disabled=true;$('#authError').textContent='';try{const result=await api('/auth/'+authMode,'POST',formObject(e.currentTarget)),isNew=authMode==='register';enterApp(result);if(isNew){toast('Chào mừng bạn về nhà. Thêm hồ sơ để bắt đầu nhé ♡');editProfile();}}catch(err){$('#authError').textContent=err.message;}finally{button.disabled=false;}};
